example.code:
#include <stdio.h>

/* Memory drawn as numbered boxes (the numbers are made up):

     address   contents      name
     -------   -----------   ----
       100     20            age
       200     100           p      <- p holds the address of age
*/

void add_one(int *p) {
    *p = *p + 1;
}

int main(void) {
    int age = 20;
    int *p = &age;

    printf("age = %d\n", age);
    printf("*p = %d\n", *p);
    printf("p points at age: %d\n", p == &age);

    *p = 21;
    printf("after *p = 21, age = %d\n", age);

    add_one(&age);
    printf("after add_one(&age), age = %d\n", age);

    int nums[3] = {10, 20, 30};
    int *q = nums;
    printf("*q = %d, *(q + 1) = %d, q[2] = %d\n", *q, *(q + 1), q[2]);
    printf("bytes between nums[0] and nums[1]: %d\n", (int)((char *)&nums[1] - (char *)&nums[0]));

    int *nothing = NULL;
    if (nothing == NULL) {
        printf("nothing points at no object\n");
    }
    return 0;
}

a.en:
void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

swap(&x, &y);

The function receives the two addresses and works on the boxes they point at, so the caller's x and y change.

a.zh:
void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

swap(&x, &y);

函数收到的是两个地址，直接操作它们指向的盒子，所以调用者的 x 和 y 都改变了。

